contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address target, uint256 amount) external payable {
        require(amount > 0);
        require(msg.value == amount);
        c.deposit{value: amount}();
        uint256 rewardBefore = c.reward(target);
        (bool ok,) = address(c).call(abi.encodeWithSignature("withdraw()"));
        require(ok);
        uint256 rewardAfter = c.reward(target);
        assert(rewardAfter == rewardBefore);
    }
}

contract InvMutTest {
    C public c;

    constructor(C _c) {
        c = _c;
    }

    function test(address who, uint256 depositAmount, uint256 rewardRate) external {
        require(who.code.length > 0);

        require(address(this).balance >= depositAmount);
        c.deposit{value: depositAmount}();

        c.setRewardRate(rewardRate);

        uint256 beforeClaimReward = c.reward(who);
        c.claim();
        uint256 afterClaimReward = c.reward(who);

        bool reverted = false;
        try this.reenterAndClaim(who, depositAmount) { } catch { reverted = true; }

        assert(!reverted ? afterClaimReward == beforeClaimReward + (depositAmount * rewardRate) : true);
    }

    function reenterAndClaim(address who, uint256 expectedBalance) external {
        uint256 beforeClaimReward = c.reward(who);
        c.withdraw();
        uint256 afterClaimReward = c.reward(who);
        require(afterClaimReward == beforeClaimReward + (expectedBalance * c.rateSnapshot(who)));
    }

    receive() external payable {
        // fallback to enable reentrancy
    }
}
